import sys, os, re
from lxml import etree

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
ns = {'w': W}

doc_path = os.path.join(sys.argv[1], 'word', 'document.xml')
tree = etree.parse(doc_path)
root = tree.getroot()
body = root.find('w:body', ns)

for i, p in enumerate(body.findall('w:p', ns)):
    ppr = p.find('w:pPr', ns)
    style = ''
    if ppr is not None:
        pstyle = ppr.find('w:pStyle', ns)
        if pstyle is not None:
            style = pstyle.get('{%s}val' % W, '')
    texts = []
    for r in p.findall('w:r', ns):
        for t in r.iter('{%s}t' % W):
            texts.append(t.text or '')
        for t in r.iter('{%s}delText' % W):
            texts.append('[DEL]' + (t.text or ''))
    txt = ''.join(texts)
    if style or txt.strip():
        print(f"[{i}] style={style!r} text={txt!r}")

